// Victory effect (sprinkles) ke liye confetti package
import Confetti from "react-confetti";
import "./App.css";

const CATEGORIES = [
  "All", "Nature", "Portrait", "Fashion", "Travel"
];

// 1. EXACT LOCAL IMAGE MAPPING (TOTAL 29 IMAGES)
const GALLERY_IMAGES = [
  { id: 1, title: "13333 avif", category: "Nature", filename: "13333.avif" },
